        System.out.println(auction.placeProxyBid("C", 200, 980));  // C's max (200) > A's max (150), C takes lead, extends close
        System.out.println(auction.placeProxyBid("A", 250, 1030)); // A returns with a higher max, retakes lead, extends close again
        System.out.println(auction.placeProxyBid("D", 300, 1100)); // arrives after the final extended close, correctly rejected

        System.out.println("Final price (should be 205): " + auction.getCurrentPrice());
        System.out.println("Final winner (should be A): " + auction.getCurrentWinner());
        System.out.println("Final close time (should be 1090): " + auction.getEndTime());
    }
}

