#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

// An English auction: proxy bidding automatically raises the price only enough
// to outbid the losing bidder's private maximum, and any bid arriving within
// the anti-sniping window pushes the closing time further out.
class Auction {
public:
    Auction(int startingPrice, int incrementAmount, long long endTime)
        : startingPrice(startingPrice), incrementAmount(incrementAmount), endTime(endTime),
          currentPrice(startingPrice), currentWinner(""), currentWinnerMaxBid(0) {}

    string placeProxyBid(const string& bidderId, int maxBid, long long currentTime) {
        if (currentTime >= endTime) {
            return bidderId + ": AUCTION_CLOSED";
        }

        string result;
        if (currentWinner.empty()) {
            currentWinner = bidderId;
            currentWinnerMaxBid = maxBid;
            currentPrice = startingPrice;
            result = bidderId + ": WINNING at " + to_string(currentPrice);
        } else if (maxBid <= currentWinnerMaxBid) {
            currentPrice = min(maxBid + incrementAmount, currentWinnerMaxBid);
            result = bidderId + ": OUTBID, current price now " + to_string(currentPrice) + " held by " + currentWinner;
        } else {
            currentPrice = min(currentWinnerMaxBid + incrementAmount, maxBid);
            currentWinner = bidderId;
            currentWinnerMaxBid = maxBid;
            result = bidderId + ": WINNING at " + to_string(currentPrice);
        }

        if (endTime - currentTime <= ANTI_SNIPE_WINDOW) {
            endTime = currentTime + EXTENSION_SECONDS; // anti-sniping: push the close further out
            result += " (auction extended to " + to_string(endTime) + ")";
        }
        return result;
    }

    int getCurrentPrice() { return currentPrice; }
    string getCurrentWinner() { return currentWinner; }
    long long getEndTime() { return endTime; }

private:
    static const int ANTI_SNIPE_WINDOW = 30;
    static const int EXTENSION_SECONDS = 60;

    int startingPrice;
    int incrementAmount;
    long long endTime;
    int currentPrice;
    string currentWinner;
    int currentWinnerMaxBid;
};

int main() {
    Auction auction(100, 5, 1000); // starting price 100, increment 5, closes at t=1000

    cout << auction.placeProxyBid("A", 150, 500) << endl;   // A: first bidder, winning at starting price
    cout << auction.placeProxyBid("B", 130, 600) << endl;   // B's max (130) <= A's max (150), A stays winning
    cout << auction.placeProxyBid("C", 200, 980) << endl;   // C's max (200) > A's max (150), C takes lead, extends close
    cout << auction.placeProxyBid("A", 250, 1030) << endl;  // A returns with a higher max, retakes lead, extends close again
    cout << auction.placeProxyBid("D", 300, 1100) << endl;  // arrives after the final extended close, correctly rejected

    cout << "Final price (should be 205): " << auction.getCurrentPrice() << endl;
    cout << "Final winner (should be A): " << auction.getCurrentWinner() << endl;
    cout << "Final close time (should be 1090): " << auction.getEndTime() << endl;

    return 0;
}

